contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 1000 and 1 <= m <= 1000",
      "description": "The dimensions n and m are integers between 1 and 1000 inclusive."
    },
    {
      "id": "P2",
      "expression": "len(grid) == n and all(len(row) == m for row in grid)",
      "description": "The input grid contains exactly n rows, each with exactly m characters."
    },
    {
      "id": "P3",
      "expression": "all(c in '#.' for row in grid for c in row)",
      "description": "Each cell in the grid is either '#' (filled) or '.' (empty)."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output == '-1' or (len(output_lines) == n and all(len(line) == m for line in output_lines))",
      "description": "If no solution exists, output is '-1'; otherwise, output is an n x m grid of characters."
    },
    {
      "id": "Q2",
      "expression": "output == '-1' or all(output_lines[i][j] == '#' if grid[i][j] == '#' else output_lines[i][j] in '0123456789' for i in range(n) for j in range(m))",
      "description": "In a valid solution, initially filled cells remain '#', and all initially empty cells are replaced by a digit."
    },
    {
      "id": "Q3",
      "expression": "output == '-1' or all((output_lines[i][j] == '#' or (output_lines[i][j] in '0123456789' and all((0 <= ni < n and 0 <= nj < m and (output_lines[ni][nj] == '#' or output_lines[ni][nj] == output_lines[i][j])) for ni, nj in [(i-1,j), (i+1,j), (i,j-1), (i,j+1)] if 0 <= ni < n and 0 <= nj < m))) for i in range(n) for j in range(m))",
      "description": "In a valid solution, all cells with the same digit form a connected component (by side) and no two different digits touch each other by side."
    },
    {
      "id": "Q4",
      "expression": "output == '-1' or all(2 <= sum(1 for i in range(n) for j in range(m) if output_lines[i][j] == d) <= 5 for d in '0123456789' if any(output_lines[i][j] == d for i in range(n) for j in range(m)))",
      "description": "In a valid solution, every connected component (represented by a digit) has a size between 2 and 5 inclusive."
    },
    {
      "id": "Q5",
      "expression": "output == '-1' or (all(output_lines[i][j] == '#' if grid[i][j] == '#' else output_lines[i][j] in '0123456789' for i in range(n) for j in range(m)) and all((output_lines[i][j] == '#' or (output_lines[i][j] in '0123456789' and all((0 <= ni < n and 0 <= nj < m and (output_lines[ni][nj] == '#' or output_lines[ni][nj] == output_lines[i][j])) for ni, nj in [(i-1,j), (i+1,j), (i,j-1), (i,j+1)] if 0 <= ni < n and 0 <= nj < m))) for i in range(n) for j in range(m)) and all(2 <= sum(1 for i in range(n) for j in range(m) if output_lines[i][j] == d) <= 5 for d in '0123456789'
